<?php
namespace Tests\Feature;
use App\Models\User;
use App\Models\Workspace;
use App\Services\Identity;
use App\Services\CommunicationAccess as C;
use App\Services\IntegrationTransport;
use App\Services\IntegrationAdapters;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Crypt;
use Tests\TestCase;
class CommunicationTest extends TestCase {
 use RefreshDatabase;
 private function team():array{$o=User::factory()->create();$a=User::factory()->create();$b=User::factory()->create();$w=Workspace::create(['name'=>'Example','type'=>'business','owner_id'=>$o->id]);$w->members()->attach([$o->id=>['role'=>'owner'],$a->id=>['role'=>'member'],$b->id=>['role'=>'member']]);return [$w,$o,$a,$b];}
 private function login(User $u,Workspace $w):static{return $this->actingAs($u)->withSession(['auth_version'=>$u->auth_version,'workspace_id'=>$w->id])->withoutVite();}
 private function conversation(array $ids,string $kind='direct'):int{$this->post('/communication',['kind'=>$kind,'name'=>'Example group','members'=>$ids])->assertRedirect();return DB::table('comm_conversations')->latest('id')->value('id');}
 private function integration(string $provider='webhook',string $secret='synthetic-test-secret-1234567890123456'):int{$this->post('/integrations',['provider'=>$provider,'label'=>'Test integration','secret'=>$secret])->assertRedirect();return DB::table('comm_integrations')->latest('id')->value('id');}
 public function test_guest_personal_and_integration_permissions():void{$this->get('/communication')->assertRedirect('/login');[$w,$o,$a]=$this->team();$this->login($o,Identity::personal($o))->get('/communication')->assertForbidden();$this->login($a,$w)->get('/communication')->assertOk();$this->get('/integrations')->assertForbidden();$this->post('/integrations',['provider'=>'github','label'=>'Denied','secret'=>'test'])->assertForbidden();}
 public function test_direct_conversation_deduplication_and_private_owner_denial():void{[$w,$o,$a,$b]=$this->team();$this->login($a,$w);$id=$this->conversation([$b->id]);$this->post('/communication/'.$id.'/messages',['body'=>'Private message'])->assertRedirect();$this->login($b,$w);$this->assertSame($id,$this->conversation([$a->id]));$this->assertDatabaseCount('comm_conversations',1);$this->get('/communication/'.$id)->assertOk()->assertSee('Private message');$this->login($o,$w)->get('/communication/'.$id)->assertNotFound();$this->post('/communication/'.$id.'/messages',['body'=>'Denied'])->assertNotFound();$this->get('/communication')->assertOk()->assertDontSee('Private message');}
 public function test_group_mentions_preferences_and_xss():void{[$w,$o,$a,$b]=$this->team();$this->login($b,$w)->post('/notifications/preferences',['email_enabled'=>0,'push_enabled'=>1,'mentions_only'=>1])->assertRedirect();$this->login($o,$w);$id=$this->conversation([$a->id,$b->id],'group');$this->post('/communication/'.$id.'/messages',['body'=>'Normal'])->assertRedirect();$this->assertDatabaseMissing('comm_notifications',['user_id'=>$b->id]);$this->post('/communication/'.$id.'/messages',['body'=>'<script>alert(1)</script>','mentions'=>[$b->id]])->assertRedirect();$this->assertDatabaseHas('comm_notifications',['user_id'=>$b->id,'kind'=>'mention']);$this->login($b,$w)->get('/communication/'.$id)->assertOk()->assertDontSee('<script>alert(1)</script>',false);$this->get('/notifications')->assertOk()->assertSee('Mention');$n=DB::table('comm_notifications')->where('user_id',$b->id)->value('id');$this->patch('/notifications/'.$n)->assertRedirect();$this->assertNotNull(DB::table('comm_notifications')->where('id',$n)->value('read_at'));}
 public function test_foreign_participants_mentions_and_notifications_denied():void{[$w,$o,$a,$b]=$this->team();[$other,$foreign]=$this->team();$this->login($o,$w);$this->post('/communication',['kind'=>'direct','members'=>[$foreign->id]])->assertNotFound();$id=$this->conversation([$a->id]);$this->post('/communication/'.$id.'/messages',['body'=>'Bad mention','mentions'=>[$b->id]])->assertSessionHasErrors('mentions');$this->post('/communication/'.$id.'/messages',['body'=>'Hello'])->assertRedirect();$n=DB::table('comm_notifications')->value('id');$this->patch('/notifications/'.$n)->assertNotFound();$this->login($foreign,$other)->get('/communication/'.$id)->assertNotFound();}
 public function test_announcement_and_email_opt_in_revocation():void{[$w,$o,$a]=$this->team();$this->login($a,$w)->post('/notifications/preferences',['email_enabled'=>1,'push_enabled'=>0,'mentions_only'=>0])->assertRedirect();$this->login($o,$w)->post('/team/announcements',['title'=>'Notice','body'=>'Private announcement'])->assertRedirect();$this->assertDatabaseHas('comm_notifications',['user_id'=>$a->id,'kind'=>'announcement','email_status'=>'pending']);config(['communication.email_enabled'=>true,'mail.default'=>'array']);$this->artisan('communication:tick')->assertExitCode(0);$this->assertDatabaseHas('comm_notifications',['user_id'=>$a->id,'email_status'=>'sent']);$this->post('/team/announcements',['title'=>'Second','body'=>'Notice'])->assertRedirect();$this->delete('/workspaces/'.$w->id.'/members/'.$a->id)->assertRedirect();$this->artisan('communication:tick')->assertExitCode(0);$this->assertDatabaseHas('comm_notifications',['user_id'=>$a->id,'email_status'=>'cancelled']);}
 public function test_encrypted_credential_and_disconnect():void{[$w,$o]=$this->team();$this->login($o,$w);$secret='synthetic-test-token';$id=$this->integration('github',$secret);$i=DB::table('comm_integrations')->where('id',$id)->first();$this->assertNotSame($secret,$i->secret);$this->assertSame($secret,Crypt::decryptString($i->secret));$this->get('/integrations')->assertOk()->assertDontSee($secret);config(['communication.integrations_enabled'=>false]);$this->patch('/integrations/'.$id,['enabled'=>1])->assertStatus(409);config(['communication.integrations_enabled'=>true]);$this->patch('/integrations/'.$id,['enabled'=>1])->assertRedirect();$this->delete('/integrations/'.$id)->assertRedirect();$this->assertDatabaseHas('comm_integrations',['id'=>$id,'secret'=>null,'enabled'=>0]);$this->patch('/integrations/'.$id,['enabled'=>1])->assertStatus(422);}
 public function test_webhook_signature_timestamp_replay_and_conflict():void{[$w,$o]=$this->team();$this->login($o,$w);$secret='synthetic-test-secret-1234567890123456';$id=$this->integration('webhook',$secret);config(['communication.integrations_enabled'=>true]);$this->patch('/integrations/'.$id,['enabled'=>1])->assertRedirect();$url='/integrations/webhook/'.$id;$raw='{"event_id":"evt1","event_type":"example"}';$ts=(string)now()->timestamp;$send=fn($body,$time,$sig)=>$this->call('POST',$url,[],[],[],['CONTENT_TYPE'=>'application/json','HTTP_X_WORKSPACE_TIMESTAMP'=>$time,'HTTP_X_WORKSPACE_SIGNATURE'=>$sig],$body);$send($raw,$ts,str_repeat('0',64))->assertUnauthorized();$old=(string)(now()->timestamp-600);$send($raw,$old,hash_hmac('sha256',$old.'.'.$raw,$secret))->assertUnauthorized();$sig=hash_hmac('sha256',$ts.'.'.$raw,$secret);$send($raw,$ts,$sig)->assertStatus(202);$send($raw,$ts,$sig)->assertOk()->assertJson(['duplicate'=>true]);$changed='{"event_id":"evt1","event_type":"different"}';$send($changed,$ts,hash_hmac('sha256',$ts.'.'.$changed,$secret))->assertStatus(409);$this->assertDatabaseCount('comm_webhook_events',1);}
 public function test_ssrf_transport_blocks_mixed_dns_and_pins_public_address():void{$t=new class extends IntegrationTransport{public array $ips=[];public array $calls=[];public function resolve(string $host):array{return $this->ips;}protected function request(string $url,string $host,string $ip,array $headers):array{$this->calls[]=[$host,$ip];return ['status'=>200,'body'=>'{}'];}};foreach(['http://example.com','https://127.0.0.1','https://a.local','https://user:pass@example.com','https://example.com:443'] as $url){try{$t->get($url);$this->fail('Unsafe URL accepted');}catch(\RuntimeException|\Illuminate\Validation\ValidationException){$this->assertTrue(true);}}$t->ips=['8.8.8.8','169.254.169.254'];try{$t->get('https://example.com');$this->fail('Unsafe DNS accepted');}catch(\RuntimeException){$this->assertCount(0,$t->calls);}$t->ips=['8.8.8.8'];$t->get('https://example.com');$this->assertSame([['example.com','8.8.8.8']],$t->calls);}
 public function test_provider_adapter_fixed_endpoints_and_rss_restrictions():void{[$w,$o]=$this->team();$this->login($o,$w);$this->post('/integrations',['provider'=>'rss','label'=>'Unsafe','url'=>'https://127.0.0.1/feed'])->assertSessionHasErrors('hostname');$this->post('/integrations',['provider'=>'rss','label'=>'Feed','url'=>'https://example.com/feed'])->assertRedirect();$id=DB::table('comm_integrations')->value('id');config(['communication.integrations_enabled'=>true]);$this->patch('/integrations/'.$id,['enabled'=>1])->assertRedirect();$t=new class extends IntegrationTransport{public function get(string $url,array $headers=[]):array{return ['status'=>200,'body'=>'<rss version="2.0"><channel/></rss>'];}};$this->app->instance(IntegrationTransport::class,$t);$this->post('/integrations/'.$id.'/test')->assertRedirect()->assertSessionHas('status','Provider connection verified.');[$url,$headers]=IntegrationAdapters::endpoint('github',[],'test-token');$this->assertSame('https://api.github.com/user',$url);$this->assertContains('Authorization: Bearer test-token',$headers);}
 public function test_manual_whatsapp_share_and_foreign_integration():void{[$w,$o]=$this->team();$this->login($o,$w);$id=$this->integration();$this->post('/communication/share',['phone'=>'8801700000000','body'=>'Hello & goodbye'])->assertOk()->assertSee('https://wa.me/8801700000000?text=Hello%20%26%20goodbye',false);[$other,$foreign]=$this->team();$this->login($foreign,$other)->patch('/integrations/'.$id,['enabled'=>0])->assertNotFound();$this->delete('/integrations/'.$id)->assertNotFound();}
}
